function applies(input){return true}
function solve({config,state,event}){var s=state===null?{v:config.version,x:config.value,a:-1,l:false}:{v:state.v,x:state.x,a:state.a,l:state.l},f=[];
if(event&&event.type==='delta'){
 if(event.base===s.v&&event.version>s.v){s.v=event.version;s.x+=event.delta;s.l=false}
 else if(event.version>s.v&&!s.l){f=[{type:'snapshot',base:s.v}];s.l=true}
}else if(event&&event.type==='snapshot'){
 if(event.version>s.v){s.v=event.version;s.x=event.value;s.l=false}
 else if(event.version===s.v&&event.value!==s.x&&!s.l){f=[{type:'snapshot',base:s.v}];s.l=true}
}else if(event&&event.type==='ack'&&event.version===s.v)s.a=s.v;
return{state:s,output:{version:s.v,value:s.x,acknowledged:s.a,effects:f}}}
